import {names,permutations,multiply,inverse,order,cycles,parity,subgroupCheck,cosets,conjugate,conjugacyClass,isNormal,symmetricClasses,factorial} from './algebra.mjs';
import {notes,quizzes} from './content.mjs';
import {chapter2Lessons,chapter2Notes,chapter2Quizzes} from './chapter2-content.mjs';
import {renderChapter2} from './chapter2.mjs';
const lessons=[
 {title:'Correspondencias y transformaciones',nav:'Transformaciones',pages:'1–6',desc:'Una transformación cambia la posición de los objetos. Componer significa aplicar una y después otra.'},
 {title:'Grupos: definiciones y ejemplos',nav:'Qué es un grupo',pages:'6–15',desc:'Un conjunto y una operación. Cuatro condiciones que permiten combinar y deshacer sus elementos.'},
 {title:'Subgrupos y teorema de Cayley',nav:'Subgrupos y Cayley',pages:'15–20',desc:'Algunas operaciones forman un grupo más pequeño. Todo grupo finito puede realizarse con permutaciones.'},
 {title:'Clases laterales y teorema de Lagrange',nav:'Clases laterales',pages:'20–23',desc:'Las clases laterales reparten un grupo en bloques del mismo tamaño. De ahí sale la divisibilidad.'},
 {title:'Clases de conjugación',nav:'Conjugación',pages:'23–28',desc:'Conjugar cambia la referencia de una operación. Descubre qué elementos quedan relacionados.'},
 {title:'Subgrupos normales, cocientes y homomorfismos',nav:'Grupos cociente',pages:'28–30',desc:'Agrupar operaciones en clases puede producir un grupo nuevo, si el subgrupo es normal.'},
 {title:'Productos directos',nav:'Productos directos',pages:'30–31',desc:'Dos grupos independientes se combinan en pares. Cada componente conserva su propia operación.'}
];
const $=s=>document.querySelector(s), content=$('#content');let chapter=1,section=1,tab='explorar',timer=null;const selection={a:1,b:3,step:2};
const opLabels=['Identidad','Giro de 120°','Giro de 240°','Reflexión, eje 1','Reflexión, eje 3','Reflexión, eje 2'];
const options=(selected=0)=>names.map((v,i)=>`<option value="${i}" ${i===selected?'selected':''}>${v} · ${opLabels[i]}</option>`).join('');
const selectField=(id,label,val=0)=>`<div class="field"><label for="${id}">${label}</label><select id="${id}">${options(val)}</select></div>`;
const setText=h=>'{'+h.map(a=>names[a]).join(', ')+'}';
const state={group:'s3',groupA:1,groupB:3,h:[0,3],cayley:1,conjG:3,conjX:1,sn:4,quotient:'rotations',qa:1,qb:1,productM:2,pair:[1,1],pairB:[1,0],power:1,matrix:[1,0,0,1],projective:1};
const answers=new Map();
function triangle(g=0){const pos=[[190,50],[75,249],[305,249]],p=permutations[g],colors=['#6ce2bc','#ffac95','#b9a7ff'];return `<svg class="triangle" viewBox="0 0 380 310" role="img" aria-label="Triángulo transformado por ${names[g]}; ${p.map((v,i)=>`vértice ${i+1} en posición ${v+1}`).join(', ')}"><defs><pattern id="grid" width="25" height="25" patternUnits="userSpaceOnUse"><path d="M25 0H0V25" fill="none" stroke="#2a3351" stroke-width=".6"/></pattern></defs><rect width="380" height="310" fill="url(#grid)"/><path d="M190 20V285M40 190H340" stroke="#47516c" stroke-dasharray="3 5"/><polygon points="190,50 75,249 305,249" fill="#7068aa18" stroke="#a5acc5" stroke-width="2"/>${pos.map(([x,y],i)=>`<text class="slot" x="${x}" y="${y+(i===0?-27:34)}" text-anchor="middle">posición ${i+1}</text>`).join('')}${p.map((slot,i)=>`<g transform="translate(${pos[slot][0]},${pos[slot][1]})"><circle r="18" fill="${colors[i]}"/><text class="vertex-label" y="6" text-anchor="middle">${i+1}</text></g>`).join('')}<circle cx="190" cy="182.6" r="3" fill="#707c9b"/></svg>`;}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
function renderComposition(){content.innerHTML=`<div class="lab"><div class="viz"><div class="viz-header"><span>SIMETRÍAS DEL TRIÁNGULO</span><span class="viz-tag">D₃ ≅ S₃ · 6 elementos</span></div><div id="shape"></div><div class="viz-bottom"><span id="stage-label"></span><strong id="stage-op"></strong></div></div><div class="control-panel"><h3>¿Importa el orden?</h3><p class="helper">Elige dos operaciones. En <span class="math">AB</span>, empieza por la de la derecha.</p><div class="select-pair">${selectField('op-a','A · segunda',selection.a)}${selectField('op-b','B · primera',selection.b)}</div><div class="result-box" aria-live="polite"><span class="mini-label">COMPOSICIÓN</span><div id="composition-result" class="result-equation"></div><p id="composition-compare"></p></div><div class="button-row"><button id="animate" class="primary-button">Ver paso a paso</button><button id="swap" class="quiet-button">Intercambiar A y B</button></div><div class="step-buttons" aria-label="Paso de la composición"><button data-step="0">1. Inicio</button><button data-step="1">2. Aplicar B</button><button data-step="2">3. Aplicar A</button></div><div class="mapping" id="mapping"></div></div></div><div class="insight"><span class="insight-symbol">≠</span><p><strong>El triángulo vuelve a encajar. Sus vértices pueden cambiar de lugar.</strong>Con los colores y las etiquetas distinguimos operaciones que dejan la misma figura geométrica. Prueba <span class="math">r</span> y <span class="math">s</span>: <span class="math">rs ≠ sr</span>.</p></div><details class="extension"><summary>De la figura a una permutación</summary><div class="detail-body"><p>Una permutación indica dónde acaba cada vértice. <span class="math">r = (1 2 3)</span> mueve 1 a 2, 2 a 3 y 3 a 1. <span class="math">s = (2 3)</span> intercambia 2 y 3, y deja 1 fijo. Las seis simetrías realizan las seis permutaciones de tres objetos.</p><p>Una correspondencia cualquiera puede juntar varios objetos en la misma imagen. Una transformación, en el sentido del capítulo, es biyectiva: cada imagen tiene exactamente un origen y existe una inversa.</p></div></details><div id="matrix-extension"></div>`;
 $('#op-a').onchange=()=>{selection.a=Number($('#op-a').value);selection.step=2;stopAnimation();updateComposition();};$('#op-b').onchange=()=>{selection.b=Number($('#op-b').value);selection.step=2;stopAnimation();updateComposition();};$('#swap').onclick=()=>{[selection.a,selection.b]=[selection.b,selection.a];selection.step=2;stopAnimation();renderComposition();};document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{stopAnimation();selection.step=Number(b.dataset.step);updateComposition();});$('#animate').onclick=()=>{stopAnimation();selection.step=0;updateComposition();let next=1;$('#animate').disabled=true;timer=setInterval(()=>{selection.step=next++;updateComposition();if(next>2)stopAnimation();},1100);};updateComposition();renderMatrix();}
function stopAnimation(){clearInterval(timer);timer=null;if($('#animate'))$('#animate').disabled=false;}
function updateComposition(){const{a,b,step}=selection,c=multiply(a,b),reverse=multiply(b,a),g=[0,b,c][step];$('#shape').innerHTML=triangle(g);$('#stage-label').textContent=['Estado inicial','Después de B','Después de B y después de A'][step];$('#stage-op').textContent=names[g];$('#composition-result').textContent=`${names[a]} · ${names[b]} = ${names[c]}`;$('#composition-compare').textContent=`Al invertir: ${names[b]} · ${names[a]} = ${names[reverse]}. ${c===reverse?'Este par sí conmuta.':'Este par no conmuta.'}`;$('#mapping').innerHTML=permutations[g].map((v,i)=>`<span>${i+1} ↦ ${v+1}</span>`).join('');document.querySelectorAll('[data-step]').forEach(b=>b.classList.toggle('active',Number(b.dataset.step)===step));}
function routeHash(s=section,t=tab,c=chapter){return (c===2?'capitulo-2/':'')+s+'/'+t;}
function activeQuizzes(){return chapter===2?chapter2Quizzes:quizzes;}
function answerKey(i){return chapter+'-'+section+'-'+i;}
function route(){
 stopAnimation();
 const legacy=location.hash.match(/^#([1-7])\/(explorar|apuntes|practicar)$/);
 const second=location.hash.match(/^#capitulo-2\/(10|[1-9])\/(explorar|apuntes|practicar)$/);
 if(second){chapter=2;section=Number(second[1]);tab=second[2];}
 else if(legacy){chapter=1;section=Number(legacy[1]);tab=legacy[2];}
 else if(location.hash!=='#main'&&location.hash!=='#fuente'){chapter=1;section=1;tab='explorar';}
 const ls=chapter===2?chapter2Lessons:lessons,l=ls[section-1],title=chapter===2?'Grupos de simetría':'Elementos de teoría de grupos';
 $('#chapter-select').value=chapter;$('#chapter-title').textContent=title;$('#top-title').textContent=title;$('#chapter-number').textContent='0'+chapter;
 document.title='Hamermesh · '+title+' · '+l.nav;
 $('.side-note').innerHTML='<span class="mini-label">EL HILO CONDUCTOR</span><p>'+(chapter===2?'Del espacio al plano.<br>De una operación al grupo.<br>Diez ideas conectadas.':'Un triángulo.<br>Seis operaciones.<br>Siete ideas conectadas.')+'</p><span class="math">'+(chapter===2?'det A = ±1':'D₃ ≅ S₃')+'</span>';
 $('#lessons').innerHTML=ls.map((v,i)=>'<a class="lesson-link '+(i+1===section?'active':'')+'" href="#'+routeHash(i+1)+'" '+(i+1===section?'aria-current="page"':'')+'><span class="num">'+String(i+1).padStart(2,'0')+'</span><span>'+v.nav+'</span></a>').join('');
 $('#section-ref').textContent='SECCIÓN '+chapter+'-'+section;$('#lesson-title').textContent=l.title;$('#lesson-desc').textContent=l.desc;$('#page-ref').textContent='Libro · pp. '+l.pages;
 document.querySelectorAll('[data-tab]').forEach(b=>{b.setAttribute('aria-selected',b.dataset.tab===tab);b.tabIndex=b.dataset.tab===tab?0:-1;});
 $('#content').setAttribute('aria-labelledby','tab-'+tab);$('#section-position').textContent=section+' de '+ls.length;$('#previous').disabled=section===1;$('#next').disabled=section===ls.length;
 const source=chapter===2?'capítulo 2, §§ 2-1 a 2-10, páginas impresas 32–67 (páginas 38–73 del PDF adjunto)':'capítulo 1, §§ 1-1 a 1-7, páginas impresas 1–31 (páginas 7–37 del PDF adjunto)';
 $('#fuente').innerHTML='<strong>Una guía para leer junto a Hamermesh.</strong><p>Basada en <cite>Group Theory and Its Application to Physical Problems</cite>, '+source+'. Explicaciones, visualizaciones y ejercicios originales para esta guía. Consulta la sección indicada del libro para la demostración y el contexto completos.</p><p>Convención: AB aplica primero B y después A. '+(chapter===2?'E es la identidad; I, la inversión espacial. Cₙ es un giro de 360°/n y también nombra su grupo generado. Sₙ aquí indica rotación-reflexión, no el grupo de permutaciones del capítulo 1. Dₙ se realiza con rotaciones del espacio. Y es la notación del libro para el grupo icosaédrico. Las coordenadas y matrices se calculan numéricamente y se muestran redondeadas.':'e es la identidad. Sₙ es el grupo de permutaciones de n objetos. D₃ se realiza con las seis simetrías planas del triángulo; Cₙ es cíclico de orden n.')+'</p>';
 if(tab==='apuntes')content.innerHTML='<article class="notes card"><span class="note-label">Lectura acompañada · § '+chapter+'-'+section+' · pp. '+l.pages+'</span>'+(chapter===2?chapter2Notes:notes)[section-1]+'</article>';
 else if(tab==='practicar')renderPractice();
 else if(chapter===2)renderChapter2(section,content);
 else [renderComposition,renderGroup,renderSubgroup,renderCosets,renderConjugacy,renderQuotient,renderProduct][section-1]();
}
function tableMarkup(labels,op,a=-1,b=-1,interactive=true){return `<div class="table-scroll"><table><caption class="sr-only">Tabla de la operación: fila A, columna B, resultado AB</caption><thead><tr><th scope="col">A · B</th>${labels.map(v=>`<th scope="col">${v}</th>`).join('')}</tr></thead><tbody>${labels.map((v,i)=>`<tr><th scope="row">${v}</th>${labels.map((_,j)=>`<td>${interactive?`<button data-cell="${i},${j}" class="${i===a&&j===b?'selected':''}" aria-label="${v} por ${labels[j]} igual a ${labels[op(i,j)]}">${labels[op(i,j)]}</button>`:labels[op(i,j)]}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function bindCells(fn){document.querySelectorAll('[data-cell]').forEach(b=>b.onclick=()=>fn(...b.dataset.cell.split(',').map(Number)));}
function groupDefinition(){switch(state.group){case 'c3':return {labels:['0','1','2'],op:(a,b)=>(a+b)%3,desc:'C₃ · suma módulo 3'};case 'c4':return {labels:['0','1','2','3'],op:(a,b)=>(a+b)%4,desc:'C₄ · suma módulo 4'};case 'v4':return {labels:['(0,0)','(1,0)','(0,1)','(1,1)'],op:(a,b)=>a^b,desc:'V₄ ≅ C₂×C₂ · suma por componentes módulo 2'};case 'mult4':return {labels:['0','1','2','3'],op:(a,b)=>(a*b)%4,desc:'{0,1,2,3} · multiplicación módulo 4'};default:return {labels:names,op:multiply,desc:'S₃ ≅ D₃ · composición de simetrías'};}}
function inspectGroup(labels,op){const all=labels.map((_,i)=>i);const closure=all.every(a=>all.every(b=>all.includes(op(a,b))));const associative=all.every(a=>all.every(b=>all.every(c=>op(op(a,b),c)===op(a,op(b,c)))));const identity=all.find(e=>all.every(a=>op(e,a)===a&&op(a,e)===a));const inverses=all.map(a=>identity===undefined?undefined:all.find(b=>op(a,b)===identity&&op(b,a)===identity));const commutative=all.every(a=>all.every(b=>op(a,b)===op(b,a)));return {closure,associative,identity,inverses,commutative};}
function renderGroup(){const{labels,op,desc}=groupDefinition();if(state.groupA>=labels.length)state.groupA=0;if(state.groupB>=labels.length)state.groupB=0;const check=inspectGroup(labels,op),a=state.groupA,b=state.groupB,result=op(a,b);content.innerHTML=`<div class="card"><div class="field" style="max-width:450px"><label for="group-model">Conjunto y operación</label><select id="group-model"><option value="s3">S₃ · simetrías del triángulo</option><option value="c3">C₃ · suma módulo 3</option><option value="c4">C₄ · suma módulo 4</option><option value="v4">V₄ · dos componentes módulo 2</option><option value="mult4">Contraejemplo · multiplicación módulo 4</option></select></div></div><div class="two-col" style="margin-top:20px"><div class="card"><h3>Una tabla para cada operación</h3><p class="helper">${desc}. Pulsa una casilla para examinar el producto.</p>${tableMarkup(labels,op,a,b)}<p class="table-caption">Fila A · columna B. Cada casilla muestra el resultado de AB.</p></div><div class="card"><span class="mini-label">PRODUCTO SELECCIONADO</span><div class="result-box" aria-live="polite"><div class="result-equation">${labels[a]} · ${labels[b]} = ${labels[result]}</div><p>${labels[b]} · ${labels[a]} = ${labels[op(b,a)]}. ${result===op(b,a)?'Este par conmuta.':'Este par no conmuta.'}</p><p>Inverso de ${labels[a]}: ${check.inverses[a]===undefined?'no existe dentro de este conjunto':labels[check.inverses[a]]}.</p></div><h3>Las cuatro condiciones</h3><div class="axioms">${[[check.closure,'Cierre','Cada producto permanece en el conjunto.'],[check.associative,'Asociatividad','Todos los triples cumplen (ab)c=a(bc).'],[check.identity!==undefined,'Identidad',check.identity===undefined?'No hay identidad.':`La identidad es ${labels[check.identity]}.`],[check.inverses.every(i=>i!==undefined),'Inversos',check.inverses.every(i=>i!==undefined)?'Cada elemento tiene un inverso.':`Sin inverso: ${labels.filter((_,i)=>check.inverses[i]===undefined).join(', ')}.`]].map(([ok,title,desc])=>`<div class="axiom"><strong class="${ok?'pass':'fail'}">${ok?'✓':'✕'} ${title}</strong>${desc}</div>`).join('')}</div><p class="helper" style="margin:16px 0 0">${check.inverses.every(i=>i!==undefined)?`Es un grupo ${check.commutative?'abeliano: todos los pares conmutan.':'no abeliano: algunos pares no conmutan.'}`:'Este conjunto con esta operación no es un grupo.'}</p></div></div><div class="challenge"><strong>Prueba un caso que falle</strong>En la multiplicación módulo 4, busca el inverso de 2. Ningún producto 2·b vale 1, la identidad. El cierre por sí solo no basta para ser un grupo.</div>`;$('#group-model').value=state.group;$('#group-model').onchange=()=>{state.group=$('#group-model').value;state.groupA=1;state.groupB=1;renderGroup();$('#group-model').focus();};bindCells((a,b)=>{state.groupA=a;state.groupB=b;renderGroup();$(`[data-cell="${a},${b}"]`).focus();});}
function subgroupControls(){return `<h3>Construye H dentro de S₃</h3><p class="helper">Activa elementos y busca qué condición se cumple o falla.</p><div class="subgroup-options">${names.map((v,i)=>`<label class="checkbox-chip"><input type="checkbox" data-h="${i}" ${state.h.includes(i)?'checked':''}><span>${v}</span></label>`).join('')}</div><div class="pills"><button data-preset="rotations">Solo rotaciones</button><button data-preset="mirror">e y s</button><button data-preset="broken">e y r</button><button data-preset="all">Todo S₃</button></div>`;}
function mountSubgroup(update){document.querySelectorAll('[data-h]').forEach(b=>b.onchange=()=>{state.h=[...document.querySelectorAll('[data-h]:checked')].map(b=>Number(b.dataset.h));update();});document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{state.h={rotations:[0,1,2],mirror:[0,3],broken:[0,1],all:[0,1,2,3,4,5]}[b.dataset.preset];document.querySelectorAll('[data-h]').forEach(c=>c.checked=state.h.includes(Number(c.dataset.h)));update();});update();}
function renderSubgroup(){content.innerHTML=`<div class="two-col"><div class="card">${subgroupControls()}</div><div class="card" id="subgroup-status" aria-live="polite"></div></div><div class="card"><h3>Cayley: permutar los seis elementos del grupo</h3><p class="helper">Elige g. Cada objeto x de S₃ se sustituye por gx. Ahora los objetos son operaciones, no vértices.</p><div class="field" style="max-width:340px"><label for="cayley-g">Multiplicar a la izquierda por g</label><select id="cayley-g">${options(state.cayley)}</select></div><div id="cayley-result" aria-live="polite"></div></div>`;mountSubgroup(()=>{const c=subgroupCheck(state.h);$('#subgroup-status').innerHTML=`<span class="mini-label">H = <span class="math">${setText(state.h)}</span></span><div class="result-box"><h3 class="${c.valid?'pass':'fail'}">${c.valid?'Sí, es un subgrupo':'Todavía no es un subgrupo'}</h3><p>${c.reason}</p></div>${c.valid?`<div class="stat-row"><div><strong>${state.h.length}</strong><span>elementos en H</span></div><div><strong>${6/state.h.length}</strong><span>índice [S₃:H]</span></div></div><p class="helper">${isNormal(state.h)?'Es normal: toda conjugación mantiene sus elementos dentro de H.':'No es normal: alguna conjugación lleva un elemento fuera de H.'}</p>`:'<p class="helper">La identidad, el cierre y los inversos tienen que funcionar con la misma operación que en S₃.</p>'}`;});$('#cayley-g').onchange=()=>{state.cayley=Number($('#cayley-g').value);updateCayley();};updateCayley();}
function updateCayley(){const p=names.map((_,i)=>multiply(state.cayley,i));$('#cayley-result').innerHTML=`<div class="cayley-mapping">${p.map((v,i)=>`<div><span class="math">${names[i]}</span><span>↦</span><strong class="math">${names[v]}</strong></div>`).join('')}</div><div class="formula">λ<sub>${names[state.cayley]}</sub> = ${cycles(p,names)}</div><p class="helper">Es una permutación de seis objetos en S₆. ${state.cayley===0?'La identidad deja todos fijos.':`No deja ningún objeto fijo; sus ciclos tienen longitud ${order(state.cayley)}, el orden de ${names[state.cayley]}.`} La imagen de e es ${names[state.cayley]}, así que podemos identificar g a partir de su permutación.</p>`;}
function cosetList(h,side){return cosets(h,side).map((c,i)=>`<div class="coset"><span class="math">${side==='left'?names[c.representative]+'H':'H'+names[c.representative]}</span><span class="math">${setText(c.elements)}</span></div>`).join('');}
function renderCosets(){content.innerHTML=`<div class="card">${subgroupControls()}<div id="coset-status" aria-live="polite"></div></div><div class="two-col" style="margin-top:20px"><div class="card"><h3>Clases izquierdas · gH</h3><p class="helper">Multiplica cada h de H por g a la izquierda.</p><div id="left-cosets" class="coset-blocks"></div></div><div class="card"><h3>Clases derechas · Hg</h3><p class="helper">Multiplica cada h de H por g a la derecha.</p><div id="right-cosets" class="coset-blocks"></div></div></div><div id="lagrange-note"></div>`;mountSubgroup(()=>{const c=subgroupCheck(state.h);if(!c.valid){$('#coset-status').innerHTML=`<div class="feedback incorrect">${c.reason} Elige un subgrupo para obtener una partición en clases.</div>`;$('#left-cosets').innerHTML='<p class="helper">Necesitamos un subgrupo H.</p>';$('#right-cosets').innerHTML='<p class="helper">Necesitamos un subgrupo H.</p>';$('#lagrange-note').innerHTML='';return;}$('#coset-status').innerHTML=`<div class="stat-row"><div><strong>6</strong><span>|S₃|</span></div><div><strong>${state.h.length}</strong><span>|H|</span></div><div><strong>${6/state.h.length}</strong><span>[S₃:H]</span></div></div>`;$('#left-cosets').innerHTML=cosetList(state.h,'left');$('#right-cosets').innerHTML=cosetList(state.h,'right');$('#lagrange-note').innerHTML=`<div class="insight"><span class="insight-symbol">${isNormal(state.h)?'=':'≠'}</span><p><strong>6 = ${6/state.h.length} bloques × ${state.h.length} elementos por bloque.</strong>${isNormal(state.h)?'Cada gH coincide con Hg: H es normal. Podremos formar un grupo cociente.':'Las particiones izquierda y derecha difieren: H no es normal. Ambas reparten los seis elementos en bloques del mismo tamaño.'}</p></div>`;});}
function renderConjugacy(){content.innerHTML=`<div class="lab"><div class="viz"><div class="viz-header"><span>LAS CLASES DE S₃</span><span class="viz-tag">1 + 2 + 3 = 6</span></div><div id="conj-classes" class="classes"></div><div class="viz-bottom"><span>Cada elemento pertenece a una clase.</span></div></div><div class="control-panel"><h3>Cambia la referencia</h3><p class="helper">Elige g y el elemento x que lo conjuga. Se aplica x⁻¹, luego g y luego x.</p><div class="select-pair">${selectField('conj-g','Operación g',state.conjG)}${selectField('conj-x','Conjugar por x',state.conjX)}</div><div id="conj-result" aria-live="polite"></div><div id="conj-shape"></div></div></div><details class="extension" open><summary>Clases en Sₙ: de los ciclos al recuento</summary><div class="detail-body"><p class="helper">Cada lista indica las longitudes de todos los ciclos, incluidos los puntos fijos. Las clases suman n! elementos.</p><div class="field" style="max-width:200px"><label for="sn">Número de símbolos n</label><select id="sn">${[3,4,5,6,7].map(n=>`<option value="${n}" ${n===state.sn?'selected':''}>S${['₀','₁','₂','₃','₄','₅','₆','₇'][n]} · ${factorial(n)} elementos</option>`).join('')}</select></div><div id="sn-result" style="margin-top:18px" aria-live="polite"></div><p class="helper" style="margin:16px 0 0">Fórmula: n! / ∏ₖ(k<sup>vₖ</sup> vₖ!), donde vₖ es el número de ciclos de longitud k. Esta clasificación usa conjugaciones dentro del Sₙ completo.</p></div></details>`;$('#conj-g').onchange=()=>{state.conjG=Number($('#conj-g').value);updateConjugacy();};$('#conj-x').onchange=()=>{state.conjX=Number($('#conj-x').value);updateConjugacy();};$('#sn').onchange=()=>{state.sn=Number($('#sn').value);updateSymmetric();};updateConjugacy();updateSymmetric();}
function updateConjugacy(){const g=state.conjG,x=state.conjX,c=conjugate(x,g),cl=conjugacyClass(g);$('#conj-classes').innerHTML=[[0],[1,2],[3,4,5]].map((set,i)=>`<div class="class-block ${set.includes(g)?'active':''}"><span class="math">${setText(set)}</span><small>${['Identidad · 1 elemento · orden 1','Giros · 2 elementos · orden 3','Reflexiones · 3 elementos · orden 2'][i]}</small></div>`).join('');$('#conj-result').innerHTML=`<div class="result-box"><span class="mini-label">xgx⁻¹</span><div class="result-equation">${names[x]} · ${names[g]} · ${names[inverse(x)]} = ${names[c]}</div><p>Clase de g: ${setText(cl)}. El orden se conserva: ${order(g)}.</p></div>`;$('#conj-shape').innerHTML=triangle(c);}
function updateSymmetric(){const cs=symmetricClasses(state.sn);$('#sn-result').innerHTML=`<div class="table-scroll"><table><caption class="sr-only">Clases de conjugación de S${state.sn}</caption><thead><tr><th scope="col">Longitudes de ciclos</th><th scope="col">Tamaño de la clase</th><th scope="col">Paridad</th></tr></thead><tbody>${cs.map(c=>`<tr><td class="math">${c.parts.join(' + ')}</td><td>${c.size}</td><td>${c.even?'Par':'Impar'}</td></tr>`).join('')}</tbody><tfoot><tr><th scope="row">${cs.length} clases</th><td>${cs.reduce((n,c)=>n+c.size,0)} = ${state.sn}!</td><td></td></tr></tfoot></table></div>`;}
function renderQuotient(){content.innerHTML=`<div class="card"><div class="field" style="max-width:460px"><label for="quotient-n">Subgrupo que agrupamos</label><select id="quotient-n"><option value="rotations">N = A₃ = {e, r, r²} · normal</option><option value="mirror">H = {e, s} · no normal</option></select></div></div><div id="quotient-main" style="margin-top:20px"></div>`;$('#quotient-n').value=state.quotient;$('#quotient-n').onchange=()=>{state.quotient=$('#quotient-n').value;updateQuotient();};updateQuotient();}
function updateQuotient(){if(state.quotient==='mirror'){$('#quotient-main').innerHTML=`<div class="card"><h3 class="fail">El producto de clases no está bien definido</h3><p>H={e,s} es un subgrupo, pero no es normal. Las clases izquierdas y derechas no coinciden.</p><div class="two-col"><div><h3>Izquierdas</h3>${cosetList([0,3],'left')}</div><div><h3>Derechas</h3>${cosetList([0,3],'right')}</div></div><div class="result-box"><span class="mini-label">MISMOS BLOQUES, DOS RESULTADOS</span><div class="result-equation">r · r = r² &nbsp; ⇒ &nbsp; r²H<br>rs · r = s &nbsp; ⇒ &nbsp; H</div><p>r y rs pertenecen al mismo bloque rH. Al multiplicarlo por rH y cambiar solo ese representante, obtenemos bloques distintos.</p></div><p>No podemos llamar grupo cociente a estos bloques con esa regla de producto. Cambia a A₃ para ver un cociente que sí funciona.</p></div>`;return;}$('#quotient-main').innerHTML=`<div class="lab"><div class="viz"><div class="viz-header"><span>HOMOMORFISMO DE PARIDAD</span><span class="viz-tag">S₃ → C₂</span></div><div class="kernel-diagram"><div><div class="fiber"><strong>{e, r, r²}</strong><small>A₃ · rotaciones · núcleo</small></div><div class="fiber"><strong>{s, rs, r²s}</strong><small>Reflexiones</small></div></div><div class="map-lines"><div>↦</div><div style="margin-top:40px">↦</div></div><div><div class="fiber target"><strong>+1</strong><small>E · identidad</small></div><div class="fiber target"><strong>−1</strong><small>F</small></div></div></div><div class="viz-bottom"><span>Se conserva el producto; se pierde el detalle.</span></div></div><div class="control-panel"><h3>Dos bloques forman C₂</h3><p class="helper">E agrupa rotaciones; F agrupa reflexiones. Pulsa un producto.</p>${tableMarkup(['E','F'],(a,b)=>a^b,state.qa,state.qb)}<div id="quotient-result" aria-live="polite"></div><p class="helper">N es normal. La elección de representante dentro de cada bloque no cambia el bloque del resultado.</p></div></div><div class="card"><h3>Comprueba que φ conserva el producto</h3><p class="helper">Selecciona dos elementos de S₃ y compara sus signos con el signo de su producto.</p><div class="select-pair" style="max-width:600px">${selectField('hom-a','Elemento a',selection.a)}${selectField('hom-b','Elemento b',selection.b)}</div><div id="hom-result" aria-live="polite"></div></div>`;bindCells((a,b)=>{state.qa=a;state.qb=b;updateQuotientResult();document.querySelectorAll('[data-cell]').forEach(c=>c.classList.toggle('selected',c.dataset.cell===`${a},${b}`));});$('#hom-a').onchange=()=>{selection.a=Number($('#hom-a').value);updateHom();};$('#hom-b').onchange=()=>{selection.b=Number($('#hom-b').value);updateHom();};updateQuotientResult();updateHom();}
function updateQuotientResult(){const labels=['E','F'];$('#quotient-result').innerHTML=`<div class="result-box"><div class="result-equation">${labels[state.qa]} · ${labels[state.qb]} = ${labels[state.qa^state.qb]}</div><p>${state.qa&&state.qb?'Dos reflexiones se combinan en una rotación. El bloque resultado es E.':'El bloque E actúa como identidad del cociente.'}</p></div>`;}
function updateHom(){const a=selection.a,b=selection.b,c=multiply(a,b),sign=s=>s>0?'+1':'−1';$('#hom-result').innerHTML=`<div class="result-box"><div class="result-equation">φ(${names[a]}${names[b]}) = φ(${names[c]}) = ${sign(parity(c))}<br>φ(${names[a]}) · φ(${names[b]}) = (${sign(parity(a))})(${sign(parity(b))}) = ${sign(parity(a)*parity(b))}</div><p>Los dos cálculos coinciden. El núcleo φ⁻¹(+1) es {e,r,r²}, y S₃/A₃ ≅ C₂.</p></div>`;}
const pairOptions=(pair,m)=>Array.from({length:2*m},(_,i)=>[Math.floor(i/m),i%m]).map(p=>`<option value="${p.join(',')}" ${p.every((v,i)=>v===pair[i])?'selected':''}>(${p.join(', ')})</option>`).join('');
function renderProduct(){const m=state.productM;content.innerHTML=`<div class="lab"><div class="viz"><div class="viz-header"><span>DOS COMPONENTES INDEPENDIENTES</span><span class="viz-tag">C₂ × C${m===2?'₂':'₃'}</span></div><div id="product-grid" class="product-grid" style="grid-template-columns:repeat(${m},1fr)"></div><div class="viz-bottom"><span id="product-stage"></span><strong id="product-current"></strong></div></div><div class="control-panel"><h3>Combinar pares</h3><div class="field"><label for="product-model">Producto directo</label><select id="product-model"><option value="2">C₂ × C₂ · grupo de Klein V₄</option><option value="3">C₂ × C₃ · isomorfo a C₆</option></select></div><p class="helper" style="margin-top:14px">Suma cada componente con su propio módulo.</p><div class="select-pair"><div class="field"><label for="pair-a">Par a</label><select id="pair-a">${pairOptions(state.pair,m)}</select></div><div class="field"><label for="pair-b">Par b</label><select id="pair-b">${pairOptions(state.pairB,m)}</select></div></div><div id="pair-result" aria-live="polite"></div><div class="field"><label for="pair-power">Repeticiones del par a: <span id="power-label"></span></label><input class="range" id="pair-power" type="range" min="0" max="6" step="1" value="${state.power}"></div><div id="pair-order" class="helper"></div></div></div><div class="insight"><span class="insight-symbol">×</span><p><strong id="product-insight"></strong>En un producto directo, las componentes se combinan por separado. Si un par recorre todos los elementos al repetirlo, es un generador del grupo.</p></div>`;$('#product-model').value=m;$('#product-model').onchange=()=>{state.productM=Number($('#product-model').value);state.pair=[1,1];state.pairB=[1,0];state.power=1;renderProduct();$('#product-model').focus();};$('#pair-a').onchange=()=>{state.pair=$('#pair-a').value.split(',').map(Number);updateProduct();};$('#pair-b').onchange=()=>{state.pairB=$('#pair-b').value.split(',').map(Number);updateProduct();};$('#pair-power').oninput=()=>{state.power=Number($('#pair-power').value);updateProduct();};updateProduct();}
function updateProduct(){const m=state.productM,a=state.pair,b=state.pairB,k=state.power,result=[(a[0]+b[0])%2,(a[1]+b[1])%m],p=[(k*a[0])%2,(k*a[1])%m];let ord=1;while((ord*a[0])%2!==0||(ord*a[1])%m!==0)ord++;$('#product-grid').innerHTML=Array.from({length:2*m},(_,i)=>[Math.floor(i/m),i%m]).map(pair=>`<button class="product-cell ${pair.every((v,i)=>v===p[i])?'active':''}" data-pair="${pair.join(',')}" aria-label="Seleccionar par (${pair.join(', ')}); ${pair.every((v,i)=>v===p[i])?'resultado actual':''}">(${pair.join(', ')})</button>`).join('');document.querySelectorAll('[data-pair]').forEach(c=>c.onclick=()=>{state.pair=c.dataset.pair.split(',').map(Number);$('#pair-a').value=state.pair.join(',');state.power=1;$('#pair-power').value=1;updateProduct();$(`[data-pair="${state.pair.join(',')}"]`).focus();});$('#product-stage').textContent=`${k} ${k===1?'repetición':'repeticiones'} del par a`;$('#product-current').textContent=`(${p.join(', ')})`;$('#power-label').textContent=k;$('#pair-result').innerHTML=`<div class="result-box"><div class="result-equation">(${a.join(', ')}) + (${b.join(', ')}) = (${result.join(', ')})</div><p>Primera componente módulo 2; segunda módulo ${m}.</p></div>`;$('#pair-order').innerHTML=`<p style="margin:14px 0">Orden de a: <strong>${ord}</strong>. ${ord===2*m?'Genera todo el grupo.':'Sus repeticiones recorren '+ord+' de los '+2*m+' elementos.'}</p><span class="math">${Array.from({length:ord+1},(_,k)=>`(${(k*a[0])%2},${(k*a[1])%m})`).join(' · ')}</span>`;$('#product-insight').textContent=m===2?'Cuatro elementos, sin elementos de orden 4: C₂×C₂ no es C₄.':'El par (1,1) tiene orden 6: C₂×C₃ es cíclico y es isomorfo a C₆.';}
function renderMatrix(){const labels=['a','b','c','d'];$('#matrix-extension').innerHTML=`<details class="extension"><summary>Más allá de las permutaciones: transforma un cuadrado con una matriz</summary><div class="detail-body"><p class="helper">La matriz A = [[a,b],[c,d]] actúa sobre vectores columna. Las figuras muestran la imagen exacta de los cuatro vértices del cuadrado unidad.</p><div class="lab"><div class="viz"><div class="viz-header"><span>TRANSFORMACIÓN LINEAL</span><span class="viz-tag">x′ = Ax</span></div><div id="matrix-shape"></div><div class="viz-bottom"><span>Original en blanco · imagen en verde</span></div></div><div class="control-panel"><div class="pills"><button data-matrix="identity">Identidad</button><button data-matrix="rotation">Giro 120°</button><button data-matrix="reflection">Reflexión</button><button data-matrix="shear">Cizalla</button><button data-matrix="singular">Aplastar</button></div><div class="matrix-fields">${labels.map((label,i)=>`<label>${label}<input class="matrix-input" type="number" min="-3" max="3" step="any" data-mat="${i}" value="${state.matrix[i]}" aria-label="Coeficiente ${label} de la matriz"></label>`).join('')}</div><div id="matrix-result" aria-live="polite"></div></div></div></div></details><details class="extension"><summary>Un invariante: la razón doble de cuatro puntos</summary><div class="detail-body"><p class="helper">Cuatro puntos x = −3, −1, 1, 3. Usa la familia f(x)=(x+t)/(0,15x+1). Para −2≤t≤2, det=1−0,15t≠0 y ninguno de estos puntos tiene denominador cero.</p><label for="projective-t">Parámetro t: <strong id="projective-label"></strong></label><input class="range" type="range" id="projective-t" min="-2" max="2" step=".1" value="${state.projective}"><div id="projective-result" aria-live="polite"></div></div></details>`;document.querySelectorAll('[data-mat]').forEach(c=>c.oninput=()=>{const fields=[...document.querySelectorAll('[data-mat]')],values=fields.map(f=>Number(f.value));if(fields.some((f,i)=>f.value===''||!Number.isFinite(values[i])||Math.abs(values[i])>3)){$('#matrix-result').innerHTML='<p class="fail">Introduce cuatro números entre −3 y 3. La figura conserva el último valor válido.</p>';return;}state.matrix=values;updateMatrix();});document.querySelectorAll('[data-matrix]').forEach(c=>c.onclick=()=>{state.matrix={identity:[1,0,0,1],rotation:[-.5,-Math.sqrt(3)/2,Math.sqrt(3)/2,-.5],reflection:[-1,0,0,1],shear:[1,1,0,1],singular:[1,1,0,0]}[c.dataset.matrix];document.querySelectorAll('[data-mat]').forEach(f=>f.value=state.matrix[Number(f.dataset.mat)]);updateMatrix();});$('#projective-t').oninput=()=>{state.projective=Number($('#projective-t').value);updateProjective();};updateMatrix();updateProjective();}
const fmt=n=>n!==0&&Math.abs(n)<.001?n.toExponential(2).replace('.',','):n.toLocaleString('es',{maximumFractionDigits:3});
function updateMatrix(){const[a,b,c,d]=state.matrix,det=a*d-b*c,pts=[[0,0],[1,0],[1,1],[0,1]],image=pts.map(([x,y])=>[a*x+b*y,c*x+d*y]),s=Math.min(65,115/Math.max(1,...image.flat().map(Math.abs))),point=([x,y])=>`${190+x*s},${175-y*s}`;$('#matrix-shape').innerHTML=`<svg class="matrix-svg" viewBox="0 0 380 325" role="img" aria-label="Cuadrado unidad y su imagen; determinante ${fmt(det)}"><path d="M30 175H350M190 25V300" stroke="#606b8b"/><text x="355" y="180" fill="#aab4d0">x</text><text x="200" y="25" fill="#aab4d0">y</text><polygon points="${pts.map(point).join(' ')}" fill="none" stroke="white" stroke-width="2" stroke-dasharray="5 4"/><polygon points="${image.map(point).join(' ')}" fill="#6ce2bc28" stroke="#6ce2bc" stroke-width="2.5"/>${image.map(p=>`<circle cx="${190+p[0]*s}" cy="${175-p[1]*s}" r="4" fill="#6ce2bc"/>`).join('')}</svg>`;$('#matrix-result').innerHTML=`<div class="result-box"><span class="mini-label">DETERMINANTE</span><div class="result-equation">ad−bc = ${fmt(det)}</div><p>${det===0?'No es invertible: el cuadrado pierde una dimensión (o dos).':'Es invertible. El área se multiplica por '+fmt(Math.abs(det))+'. '+(det<0?'Invierte la orientación.':'Conserva la orientación.')}</p></div>`;}
function updateProjective(){const xs=[-3,-1,1,3],t=state.projective,ys=xs.map(x=>(x+t)/(.15*x+1)),cr=([a,b,c,d])=>((a-b)/(c-b))/((a-d)/(c-d));$('#projective-label').textContent=fmt(t);$('#projective-result').innerHTML=`<div class="result-box"><p>Imágenes: ${ys.map(fmt).join(' · ')}</p><div class="crossratio-row"><div>Antes<br><span>R = ${fmt(cr(xs))}</span></div><div>Después<br><span>R′ = ${fmt(cr(ys))}</span></div><div>Determinante<br><span>${fmt(1-.15*t)}</span></div></div><p>Las distancias cambian, pero la razón doble se conserva. Se muestran tres decimales.</p></div>`;}
function renderPractice(){const qs=activeQuizzes()[section-1];content.innerHTML=`<div class="practice"><div class="practice-heading"><div><h3>Comprueba que puedes explicarlo</h3><p class="helper">Preguntas originales sobre esta sección. Elige una respuesta y lee el razonamiento.</p></div><span class="practice-score" id="practice-score"></span></div>${qs.map((q,i)=>{const saved=answers.get(answerKey(i));return `<section class="question"><span class="mini-label">PREGUNTA ${i+1} DE ${qs.length}</span><h3 style="margin-top:10px">${q.q}</h3><fieldset style="border:0;padding:0;margin:0"><legend class="sr-only">${q.q}</legend><div class="answer-options">${q.a.map((a,j)=>`<label class="answer-option"><input type="radio" name="question-${i}" value="${j}" ${saved?.choice===j?'checked':''}><span>${a}</span></label>`).join('')}</div></fieldset><button class="primary-button" data-check="${i}">Comprobar respuesta</button><div id="feedback-${i}" aria-live="polite">${saved?feedbackMarkup(q,saved.choice):''}</div></section>`;}).join('')}<button id="reset-practice" class="quiet-button">Reiniciar esta sección</button></div>`;document.querySelectorAll('[data-check]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.check),selected=$(`input[name="question-${i}"]:checked`);if(!selected){$('#feedback-'+i).innerHTML='<p class="helper" style="margin-top:12px">Selecciona una respuesta para comprobarla.</p>';return;}const choice=Number(selected.value);answers.set(answerKey(i),{choice});$('#feedback-'+i).innerHTML=feedbackMarkup(qs[i],choice);updateScore();});$('#reset-practice').onclick=()=>{qs.forEach((_,i)=>answers.delete(answerKey(i)));renderPractice();};updateScore();}
function feedbackMarkup(q,choice){return `<div class="feedback ${choice===q.correct?'correct':'incorrect'}"><strong>${choice===q.correct?'Correcto.':'Revisa esta idea.'}</strong> ${q.why}</div>`;}
function updateScore(){const qs=activeQuizzes()[section-1],checked=qs.filter((_,i)=>answers.has(answerKey(i))).length,correct=qs.filter((q,i)=>answers.get(answerKey(i))?.choice===q.correct).length;$('#practice-score').textContent=`${correct}/${qs.length} correctas · ${checked} comprobadas`;}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>location.hash=routeHash(section,b.dataset.tab));
$('#chapter-select').onchange=()=>{location.hash=routeHash(1,'explorar',Number($('#chapter-select').value));$('#main').scrollIntoView();};
$('.tabs').onkeydown=e=>{const tabs=[...document.querySelectorAll('[data-tab]')],i=tabs.indexOf(document.activeElement);let next;if(e.key==='ArrowRight')next=(i+1)%tabs.length;if(e.key==='ArrowLeft')next=(i+tabs.length-1)%tabs.length;if(e.key==='Home')next=0;if(e.key==='End')next=tabs.length-1;if(next!==undefined){e.preventDefault();tabs[next].click();tabs[next].focus();}};
$('#previous').onclick=()=>{location.hash=routeHash(Math.max(1,section-1));$('#main').scrollIntoView();};$('#next').onclick=()=>{location.hash=routeHash(Math.min(chapter===2?10:7,section+1));$('#main').scrollIntoView();};
$('#share').onclick=async()=>{const url=new URL(location.href);url.hash=routeHash();try{await navigator.clipboard.writeText(url.href);toast('Enlace de esta sección copiado.');}catch{const area=document.createElement('textarea');area.value=url.href;area.setAttribute('aria-label','Enlace de esta sección');area.style.position='fixed';area.style.top='0';document.body.append(area);area.select();const copied=document.execCommand('copy');area.remove();if(copied)toast('Enlace de esta sección copiado.');else toast('Comparte la dirección que aparece en el navegador.');}};
